register_round_five_help <- function(){h<-get("parameter_help",envir=parent.frame());for(pre in c("ma_","ds_"))for(k in c("run_source","run_name","config_file","reps","seed","view_scenario","view_trial","sample_run"))h[paste0(pre,k)]<-h[paste0("hg_",k)]
  common<-c(unit="日/周/月，默认月。时间、风险/入组/退出率及页面CSV内时间和退出率同步转换；HR/权重/N不转换。",origin="研究起点日期，用于观察ADTTE日历字段；分析使用连续日。",design="共享对照一次Final；按Stage1选择的独立新队列两阶段；或同一Stage1患者PFS筛选/OS确认的2-in-1。Stage2始终为新患者。",endpoint="一次Final和同终点两阶段的单终点标签；2-in-1固定PFS筛选、OS确认。",model="共享Control基准事件分布，指数/Weibull/PWE。治疗分布通过Sg(t)=S0(t)^HR生成；2-in-1改用指数进展和状态无关死亡。",exp_basis="指数中位时间或风险率二选一，lambda=log(2)/m。",median="Control中位时间，正值；默认12月。Weibull尺度由中位时间和形状换算。",rate="Control指数风险率，1/当前单位，默认log(2)/12每月。",shape="Weibull形状k>0，默认1.2；k=1为指数。",cuts="PWE风险年龄切点正递增，默认6,12月。",rates="PWE各段每单位风险率，个数=切点数+1，非负、末段须正。",progression_rate="Control进展指数风险率，每单位，默认log2/12每月。",death_rate="Control状态无关死亡风险率，每单位，默认log2/30每月。02与12使用同一风险，以便OS风险倍数有明确真值。",arms="严格CSV三列arm,weight,dropout_rate，首Control及1–5试验臂。臂名英文数字下划线，权重正，退出率非负。按预定配额取整并随机排列；Stage2选中臂和Control权重重新归一。",scenario_single="label及hr_各试验臂；例label,hr_A,hr_B。HR<1有益，HR>=1为本方向真实零效应/有害；支持全零效应和部分零效应情景。",scenario_joint="2-in-1严格label,hr_各臂,prog_各臂；hr是OS死亡风险倍数，prog是进展风险倍数。PFS和OS不当作独立终点。",enroll_rate="每阶段总体恒定Poisson入组率，人/当前单位；Stage2从Stage1后开始新的入组过程。",n1="Stage1全部臂总计划N，20–3000；实际截点之前可能尚未全部入组，未入组不计作观察患者。",n2="Stage2独立新队列总计划N，20–3000，包含新Control及选择臂；不是每臂人数，也不含Stage1。",stage1="一次Final日期或Stage1共同IA，从研究起点计时，默认18月。",max="两阶段共同Final，从研究起点计时，须晚于Stage1，默认42月。",test="log-rank为固定日历截点的正态近似；精确landmark为固定随访年龄生存比例Fisher单侧检验，要求无退出且整个预定比较完成年龄随访，否则整项p=1。",landmark="精确分支共同生存参考年龄，默认12月；不是研究日历DCO。",multiplicity="Bonferroni或Holm，家族始终为最初所有试验臂；共享对照的相关性不要求独立。",alpha="整个预定试验臂家族单侧alpha，常用0.025；不会按选择数重置家族。",confirmation="Stage2单独检验，或固定权重逆正态组合。2-in-1组合时用Stage1 OS p和Stage2 OS p，PFS只选择。",w1="预定逆正态Stage1系数w1，0.01–0.99，w2=sqrt(1-w1^2)；不是信息比例，不随实际事件数改变。",screen_p="Stage1筛选p阈值0.0001–1，默认0.5；按p从小到大保留，臂名打破同p。没有达标臂则停止，不拒绝。",select_k="最多保留臂数1–试验臂数，默认1。未选择臂最终p=1，纳入原家族。")
  for(pre in c("ma_","ds_"))for(k in names(common))h[paste0(pre,k)]<-common[[k]]
  extra<-c(ds_candidates="页面CSV七列label,n1,n2,stage1,max,landmark,w1，时间使用当前显示单位；最多20候选，导出内部列为连续日。仅候选内选择，不外推。",ds_power_target="每个有真实有效臂情景，至少一个有效臂声明概率的MC下界须达到该阈值；默认0.8。",ds_fwer_limit="每个含真实零效应/有害臂情景，至少一个此类臂声明概率MC上界须不超过此限；默认0.05。它与设计alpha不同。",ds_confidence="搜索候选×真值情景及功效/FWER界使用预定同时Monte Carlo置信度；默认0.95。不是试验效应CI。",ds_day_cost="预定成本=计划N1(+N2)+此系数×Final日数，单位人数成本/日；默认0。与结果功效无关，平局按N/候选ID。",rc_source="填写参数或导入本入口冻结JSON二选一；不需要患者上传。",rc_file="event_pred.reverse_config.v1无损配置JSON，最多5MB；只读取参数。",rc_solve="一次反求一个量：风险倍数、未来总计划N、DCO；或给定参考年龄生存率反求风险倍数。其余参数冻结。",rc_n0="研究起点立即入组且风险年龄0的初始患者数，非负整数；不是实际IA存活队列。",rc_future_n="未来有限计划总人数，非负整数；每人的入组时间均匀分布于0到指定入组期，不能解释为不限人数Poisson率。",rc_accrual="有限计划人数的均匀入组期，正；不是额外随访期。",rc_dco="研究起点至共同截点，正；若早于入组期结束，只累计已入组部分。",rc_dropout="独立指数永久退出率，每当前单位；0表示无退出。",rc_hazard_q="共同风险倍数q，S(t)=S0(t)^q；0.001–100，与退出率不共变。",rc_target="截至DCO期望累计临床事件数，可为非整数；不是保证事件数或功效目标。",rc_age="模型潜在事件的风险年龄，用于生存率反求，默认12月。",rc_survival="该年龄的目标潜在事件生存率0.0001–0.9999；不含退出或入组机制。",rc_lower="预定求解下界。风险倍数0.001–100；人数0–100000；DCO0–3650日。目标超出上下界时停止，不自动扩展。",rc_upper="预定求解上界，同下界单位。未来N输出连续解及向上取整人数，并重算整数方案期望。")
  h[names(extra)]<-extra;for(k in c("unit","model","exp_basis","median","rate","shape","cuts","rates"))h[paste0("rc_",k)]<-common[[k]];assign("parameter_help",h,envir=parent.frame())}
r5_model_ui <- function(pre){id<-function(k)paste0(pre,k);tagList(selectInput(id("model"),"Control事件模型",c("指数"="exponential","Weibull"="weibull","分段指数"="pwe")),conditionalPanel(paste0("input.",id("model")," === 'exponential'"),radioButtons(id("exp_basis"),"指数参数",c("中位时间"="median","风险率"="rate"),inline=TRUE),conditionalPanel(paste0("input.",id("exp_basis")," === 'rate'"),numericInput(id("rate"),"风险率（每月）",log(2)/12,min=.00001))),conditionalPanel(paste0("input.",id("model")," === 'weibull' || (input.",id("model")," === 'exponential' && input.",id("exp_basis")," === 'median')"),numericInput(id("median"),"中位时间（月）",12,min=.001)),conditionalPanel(paste0("input.",id("model")," === 'weibull'"),numericInput(id("shape"),"Weibull形状",1.2,min=.01,max=20)),conditionalPanel(paste0("input.",id("model")," === 'pwe'"),fields(textInput(id("cuts"),"风险年龄切点（月）","6,12"),textInput(id("rates"),"各段风险率（每月）","0.04,0.06,0.05"))))}
