        selectInput("rc_solve","求解变量",c("目标事件数→风险倍数"="hazard","目标事件数→未来计划N"="future_n","目标事件数→DCO"="dco","目标生存率→风险倍数"="survival")),r5_model_ui("rc_")),
      conditionalPanel("input.rc_solve !== 'survival'",
        section("冻结过程",
