          numericInput("rc_target","目标期望事件数",200,min=0))),
      conditionalPanel("input.rc_solve === 'survival'",section("目标生存率",fields(numericInput("rc_age","生存参考年龄（月）",12,min=.001),numericInput("rc_survival","目标生存率",.6,min=.0001,max=.9999)))),
