    div(class="export-bar",downloadButton("rc_config_download","冻结配置JSON"),downloadButton("rc_result_download","结果RDS"),downloadButton("rc_overview_download","结果CSV"),downloadButton("rc_curve_download","曲线CSV"),downloadButton("rc_trace_download","求解记录CSV"),downloadButton("rc_report_download","报告Markdown"),downloadButton("rc_script_download","复现R脚本")))
}
